<!--vbase-->
<template>
  <q-btn-dropdown
    v-model="export_dropdown"
    split
    unelevated
    :class="''"
    color="primary"
    class="export-btn q-mr-sm"
    no-caps
    :disable="export_request_in_flight"
    @click="dropdownClicked()"
  >
    <template v-slot:label>
      <q-icon name="ios_share" color="white-8" style="font-size: 18px" />
      <span class="export-label"> {{ $t('export') }}</span>
    </template>
    <q-list class="text-center">
      <q-item
        id="export_po_btn"
        clickable
        v-close-popup
        @click="confirmAndExport()"
        class="border-bottom-bdbdbd min-height-38"
      >
        <q-item-section avatar class="list-avatar">
          <q-icon name="ios_share" color="grey-8" style="font-size: 18px" />
        </q-item-section>
        <q-item-section>
          <q-item-label>{{ $t('confirm_export') }}</q-item-label>
        </q-item-section>
      </q-item>
      <q-item
        clickable
        v-close-popup
        v-if="is_alternate_export_on"
        @click="validateAndAlternateExport()"
        class="border-bottom-bdbdbd min-height-38"
      >
        <q-item-section avatar class="list-avatar">
          <q-icon name="ios_share" color="grey-8" style="font-size: 18px" />
        </q-item-section>
        <q-item-section>
          <q-item-label>{{ $t('doc_alternate_export') }}</q-item-label>
        </q-item-section>
      </q-item>

      <q-item
        id="reject_btn"
        clickable
        v-close-popup
        @click="rejectDoc()"
        class="border-bottom-bdbdbd min-height-38"
      >
        <q-item-section avatar class="list-avatar">
          <q-icon name="ios_share" color="grey-8" style="font-size: 18px" />
        </q-item-section>
        <q-item-section>
          <q-item-label>{{ $t('reject') }}</q-item-label>
        </q-item-section>
      </q-item>
    </q-list>
  </q-btn-dropdown>

  <!-- <f-btn
      id="export_po_btn"
      @click="confirmAndExport()"
      icon="ios_share"
      class="q-mr-sm"
    >
      <q-tooltip>{{ $t('confirm_export') }}</q-tooltip>
    </f-btn>

    <f-btn v-if="is_alternate_export_on"
      @click="validateAndAlternateExport()"
      icon="ios_share"
      appearance="alternate"
    >
      <q-tooltip>{{ $t('doc_alternate_export') }}</q-tooltip>
    </f-btn> -->

  <q-dialog v-model="confirm_amount_difference" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section
        class="row items-center"
        style="justify-content: center; display: flex"
      >
        <span class="q-ml-sm">{{ $t('amount_pending_message') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <autoAccountingBtn :show_icon_btn="false" />
        <!--
          DRFS-741: no auto_match_and_export marker here, deliberately. Reaching
          this dialog means the pending amount is positive and a person chose to
          run anyway -- that is an explicit human export, not the automatic
          Auto-Match-and-Export action, so the API must not refuse it on the
          module switch. The automatic callers never get here: they return early
          on a positive pending amount (PO-matching.vue, Screen-po-matching-v3.vue).
        -->
        <f-btn
          :label="$t('run_anyway')"
          v-close-popup
          @click="validateConfigurationAndExport()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import cache from 'src/utils/cache';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import helperMixin from 'src/mixins/helperMixin';
import type { dynamicObj } from 'src/pages/assets';
import poActionsUtil from 'src/utils/poActionsUtil';
import { ApiExceptions } from 'src/exceptions/index';
import { documentDetailApiService } from 'src/services';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import { notify } from 'src/components/notifications/notify';
import { export_request_in_flight } from 'src/services/document/exportRequestGuard';
import autoAccountingBtn from 'src/pages/ValidationScreen/components/autoAccountingBtn.vue';
import {
  allowedDocTypes,
  doc_alternate_export_setting,
  doc_alternate_export_export_config,
  doc_alternate_export_status,
} from 'src/constants';
import {
  useDocLockStore,
  useDocumentStore,
  useDashboardStore,
  usePoMatchStore,
  useDocAttributesStore,
} from 'src/store/main';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin, poActionsUtil, displayFieldLabel, cache],
  emits: ['setSavePendingStatus'],
  props: {
    enableExportButton: Boolean,
    isValidationView: {
      type: Boolean,
      default: false,
    },
    confirmOnPoLeave: {
      type: Boolean,
      default: false,
    },
  },
  components: {
    autoAccountingBtn,
  },
  watch: {
    loading_data: {
      handler: function (newVal, oldVal) {
        if (newVal === false) {
          this.isAlternateExportOn();
        }
      },
    },
  },
  data() {
    return {
      docId: '',
      allowedDoctypes: allowedDocTypes,
    };
  },
  mounted: function () {
    // before browser or tab close clear the cache data
    window.addEventListener('beforeunload', this.onTabClose);
    window.addEventListener('confirm_and_export', this.confirmAndExport);
    document.addEventListener('reject_document', this.rejectEventHandler);
    this.docId = this.$route.params.id as string;
    this.isAlternateExportOn();
  },
  unmounted: function () {
    window.removeEventListener('beforeunload', this.onTabClose);
    window.removeEventListener('confirm_and_export', this.confirmAndExport);
  },
  methods: {
    routeToDashboard() {
      window.removeEventListener('beforeunload', this.onTabClose);
      this.releaseDocLock({ doc_id: this.record.doc_id });
      this.$router.push('/dashboard');
    },

    async validateConfigurationAndExport(auto_match_and_export = false) {
      const actionLockAcquired = await this.hasActionAcquiredLock();
      if (!actionLockAcquired) {
        let errorMessage = this.getDocLockError();
        if (errorMessage) {
          notify.error(errorMessage);
        }
        return;
      }

      try {
        this.exportData(auto_match_and_export).catch();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    async exportData(auto_match_and_export = false) {
      let data: any = this.record;

      this.showLoading();

      if (data.hasOwnProperty('table_data_copy')) {
        delete data['table_data_copy'];
      }

      let response: any;
      try {
        this.$emit('setSavePendingStatus', false);

        notify.dismissAll();
        let formData = new FormData();
        formData.append('data', JSON.stringify(data));
        // DRFS-741: mark the export the PO page performs by itself right after
        // Auto Match, so the API enforces the org-wide "PO Auto Match and
        // Export" module switch server-side instead of trusting this client to
        // have checked it. Never set for a person pressing Export -- that is an
        // explicit instruction, not this convenience action.
        if (auto_match_and_export) {
          formData.append('auto_match_and_export', 'true');
        }
        response = await documentDetailApiService.validate_and_export(
          this.docId,
          formData,
        );

        if (response.success === true) {
          await this.dashboardFiltersAfterExport();
          this.routeToDashboard();
          return;
        }

        if (response.success === false) {
          throw response;
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    onTabClose(e: any) {
      if (!this.confirmOnPoLeave) {
        return;
      }
      // let eventName = SessionStorage.has('event_name') ? SessionStorage.getItem('event_name') as string : null;
      // if(eventName && eventName === 'language_change') {
      //   return;
      // }
      e.preventDefault();
      e.returnValue = '';
      // this.clearSelectedSessionStorage();
    },

    dropdownClicked() {
      if (this.is_alternate_export_on) {
        this.export_dropdown = !this.export_dropdown;
        return;
      }
      this.confirmAndExport();
    },

    confirmAndExport(auto_match_and_export = false) {
      // Also registered as a window 'confirm_and_export' listener, which invokes
      // it with an Event object, and bound to click handlers that pass nothing.
      // Only an explicit boolean true means "the PO page is auto-exporting".
      const isAutoMatchAndExport = auto_match_and_export === true;
      try {
        this.amount_error = false;
        let pendingAmount = parseFloat(
          this.pending_amount.replace(/[^0-9]/g, ''),
        );
        if (
          this.pending_amount &&
          this.pending_amount != '' &&
          pendingAmount > 0
        ) {
          // show warnin
          this.confirm_amount_difference = true;
          this.amount_error = true;
          return;
        }

        this.validateConfigurationAndExport(isAutoMatchAndExport);
      } catch (err) {
        logError(err);
      }
    },

    isAlternateExportOn() {
      this.is_alternate_export_on = false;
      if (
        this.doc_attributes &&
        this.doc_attributes.hasOwnProperty(doc_alternate_export_setting) &&
        this.doc_attributes[doc_alternate_export_setting] === true
      ) {
        this.is_alternate_export_on = true;
      }
    },

    async validateAndAlternateExport() {
      try {
        this.showLoading();
        this.$emit('setSavePendingStatus', false);
        if (!(await this.saveAndValidateBeforeAlternateExport())) {
          return;
        }
        await this.doAlternateExport();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async saveAndValidateBeforeAlternateExport() {
      notify.info(this.$t('saving_data'));
      const response: dynamicObj = await this.saveAndValidate();

      if (response.success === false) {
        const event = new CustomEvent('display_fields_errors', {});
        document.dispatchEvent(event);
        notify.error(response.message);
        return false;
      }
      return true;
    },

    async doAlternateExport() {
      let data = {} as dynamicObj;
      data['doc_id'] = this.docId;
      data['export_config_id'] = this.getAttriValueByKeyAndSubOrgId(
        doc_alternate_export_export_config,
        this.getDocSubOrgId(),
      );
      data['status_after_export'] = this.getAttriValueByKeyAndSubOrgId(
        doc_alternate_export_status,
        this.getDocSubOrgId(),
      );
      data['check_pending_tasks'] = true;
      data['is_alternate_export'] = true;

      const response = await documentDetailApiService.do_alternate_export(data);
      if (response.success === true) {
        this.routeToDashboard();
      }

      if (response.success === false) {
        throw response;
      }
    },

    rejectEventHandler(e: any) {
      this.rejectDoc();
    },

    async rejectDoc() {
      try {
        if (this.isReadOnly) {
          return;
        }
        this.showLoading();
        this.$emit('setSavePendingStatus', false);
        const response = await this.rejectDocument(this.docId);
        if (response.success === true) {
          this.routeToDashboard();
          return;
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { record, doctype, language_origin, notifications } =
      storeToRefs(doc_store);
    const { saveAndValidate, rejectDocument, getDocSubOrgId, saveDocument } =
      doc_store;

    const doc_lock_store = useDocLockStore();
    const { hasActionAcquiredLock, releaseDocLock, getDocLockError } =
      doc_lock_store;

    const dashboard_store = useDashboardStore();
    const { dashboardFiltersAfterExport } = dashboard_store;

    const doc_attribute_store = useDocAttributesStore();
    const { model: doc_attributes, loading_data } =
      storeToRefs(doc_attribute_store);
    const { getAttriValueByKeyAndSubOrgId } = doc_attribute_store;

    const po_match_store = usePoMatchStore();
    const { pending_amount, amount_error } = storeToRefs(po_match_store);

    return {
      getDocSubOrgId,
      getAttriValueByKeyAndSubOrgId,
      rejectDocument,
      amount_error,
      pending_amount,
      dashboardFiltersAfterExport,
      record,
      doctype,
      language_origin,
      notifications,
      releaseDocLock,
      exportButtonWidth: ref('61'),
      hasActionAcquiredLock,
      getDocLockError,
      confirm_amount_difference: ref(false),

      is_alternate_export_on: ref(false),
      doc_attributes,
      loading_data,
      saveAndValidate,
      export_request_in_flight,

      export_dropdown: ref(false),
      saveDocument,
    };
  },
});
</script>

<style>
.list-avatar {
  min-width: 0px;
  padding-right: 9px;
  font-size: 10px;
  margin-bottom: 4px;
}

.export-btn .q-btn-item {
  padding-left: 8px;
  padding-right: 8px;
}

.export-label {
  padding-top: 4px;
  padding-left: 4px;
}
